const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { performance } = require('node:perf_hooks');
const { webcrypto } = require('node:crypto');

const manifestPath = path.resolve(process.argv[2]);
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
const input = new TextDecoder('utf-8', { fatal: true }).decode(fs.readFileSync(process.argv[3]));
const files = new Map(Object.entries(manifest.assets));
const readAssets = [];
const statuses = [];
const stdout = [];
const stderr = [];
let phase = 'loading';
let finished = false;
let context;

function resource(value) {
    const url = new URL(typeof value === 'string' || value instanceof URL ? value : value.url, manifest.worker);
    const name = files.get(url.href);
    if (typeof name !== 'string' || !/^[a-z0-9_.-]+$/i.test(name) || name === '.' || name === '..') {
        throw new Error('Worker requested an asset outside the recorded set: ' + url.href);
    }
    readAssets.push(url.href);
    return fs.readFileSync(path.join(path.dirname(manifestPath), name));
}

function deliver(message) {
    queueMicrotask(() => {
        if (!finished) {
            try {
                context.onmessage({ data: message });
            } catch (error) {
                fail(error);
            }
        }
    });
}

function fail(error) {
    if (finished) return;
    finished = true;
    clearTimeout(deadline);
    const detail = { error: String(error.stack || error), phase, statuses, stdout, stderr, readAssets };
    process.stderr.write(JSON.stringify(detail) + '\n', () => process.exit(1));
}

function reply(message) {
    switch (message.target) {
        case 'status':
            statuses.push(message.status);
            if (message.status !== 'Ready...') return;
            if (phase === 'loading') {
                phase = 'file';
                deliver({ target:'file', name:'hello.ox', encoding:'utf8', content:input, preMain:true });
            } else if (phase === 'file') {
                phase = 'running';
                deliver({ target:'runmain', args:['-I/ox/include;/ox;/apps', '/hello.ox'],
                    preMain:true, local:false, fileName:'hello.ox' });
            }
            return;
        case 'stdout':
            stdout.push(String(message.content));
            return;
        case 'stderr':
            stderr.push(String(message.content));
            return;
        case 'tick':
            deliver({ target:'tock', id:message.id });
            return;
        case 'setimmediate':
            deliver({ target:'setimmediate' });
            return;
        case 'main': {
            if (phase !== 'running' || !Number.isInteger(message.value)) {
                fail(new Error('Unexpected Ox worker result.'));
                return;
            }
            finished = true;
            clearTimeout(deadline);
            const result = { oxExitCode:message.value, stdout, stderr, statuses, readAssets };
            process.stdout.write(JSON.stringify(result) + '\n', () => process.exit(message.value === 0 ? 0 : 1));
            return;
        }
        case 'ShowDrawWindow':
            fail(new Error('Unexpected drawing window request from the Ox example.'));
            return;
        default:
            return;
    }
}

const deadline = setTimeout(() => fail(new Error('No Ox result in 40 seconds.')), 40000);
process.on('unhandledRejection', fail);
context = vm.createContext({
    ArrayBuffer, SharedArrayBuffer, Uint8Array, WebAssembly, URL,
    Response, Headers, TextEncoder, TextDecoder, performance,
    crypto: webcrypto,
    setTimeout, clearTimeout, setInterval, clearInterval, queueMicrotask,
    location: new URL(manifest.worker),
    navigator: { hardwareConcurrency: 2, userAgent: 'OxRun local worker test' },
    WorkerGlobalScope: class WorkerGlobalScope {},
    onmessage: null,
    postMessage: reply,
    importScripts: (...urls) => urls.forEach(url => vm.runInContext(resource(url).toString('utf8'), context, { filename:url })),
    fetch: async url => {
        const pathname = new URL(typeof url === 'string' || url instanceof URL ? url : url.url, manifest.worker).pathname;
        const type = pathname.endsWith('.wasm') ? 'application/wasm' : 'application/octet-stream';
        const bytes = resource(url);
        return new Response(bytes, { headers:{ 'Content-Type':type, 'Content-Length':String(bytes.length) } });
    },
});
vm.runInContext('globalThis.self = globalThis;',context);
try {
    vm.runInContext(resource(manifest.worker).toString('utf8'), context, { filename:manifest.worker, timeout:15000 });
} catch (error) {
    fail(error);
}
